            "跟着你",
            "不走"
        ];

        // 点击时的动画类型
        const animClasses = ['slime-squish', 'slime-stretch', 'slime-bounce'];

        function slimeInteract(element, slimeId) {
            const body = element.querySelector('.slime-body');
            const speech = document.getElementById('speech-' + slimeId);

            // 移除之前的动画
            animClasses.forEach(c => body.classList.remove(c));
            void body.offsetWidth; // 触发重绘

            // 随机动画
            const randomAnim = animClasses[Math.floor(Math.random() * animClasses.length)];
            body.classList.add(randomAnim);

            // 显示台词（如果有对应气泡）
            if (speech) {
                const randomQuote = slimeQuotes[Math.floor(Math.random() * slimeQuotes.length)];
                speech.textContent = randomQuote;
                speech.classList.add('show');

                setTimeout(() => {
                    speech.classList.remove('show');
                }, 1800);
            }

            // 动画结束后移除
            setTimeout(() => {
                body.classList.remove(randomAnim);
            }, 500);
        }
